import{_ as i,o as a,c as n,a2 as t}from"./chunks/framework.CHeM0PsO.js";const u=JSON.parse('{"title":"Specification-Driven Development Workflow","description":"","frontmatter":{"sourceUrl":"https://github.com/sovereignfs/sovereign-os/blob/main/docs/development/workflow.md"},"headers":[],"relativePath":"sovereign-os/development/workflow.md","filePath":"sovereign-os/development/workflow.md"}'),r={name:"sovereign-os/development/workflow.md"};function o(s,e,l,c,d,p){return a(),n("div",null,[...e[0]||(e[0]=[t(`<h1 id="specification-driven-development-workflow" tabindex="-1">Specification-Driven Development Workflow <a class="header-anchor" href="#specification-driven-development-workflow" aria-label="Permalink to &quot;Specification-Driven Development Workflow&quot;">​</a></h1><p><strong>Status:</strong> Draft<br><strong>Version:</strong> 0.1</p><h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><p>Sovereign Home OS is human-directed and AI-assisted. AI agents can research, propose, implement, review, test, and document work, but the project owner remains responsible for product direction, risk acceptance, and approval of major decisions.</p><h2 id="planning-chain" tabindex="-1">Planning Chain <a class="header-anchor" href="#planning-chain" aria-label="Permalink to &quot;Planning Chain&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Concept</span></span>
<span class="line"><span>  -&gt; master plan</span></span>
<span class="line"><span>  -&gt; phase plan</span></span>
<span class="line"><span>  -&gt; research or experiment</span></span>
<span class="line"><span>  -&gt; RFC</span></span>
<span class="line"><span>  -&gt; decision/ADR</span></span>
<span class="line"><span>  -&gt; implementation plan</span></span>
<span class="line"><span>  -&gt; issue</span></span>
<span class="line"><span>  -&gt; code and tests</span></span>
<span class="line"><span>  -&gt; release</span></span>
<span class="line"><span>  -&gt; retrospective</span></span></code></pre></div><p>Not every change requires every document. Every change requires enough context to be independently reviewed and tested.</p><h2 id="roles" tabindex="-1">Roles <a class="header-anchor" href="#roles" aria-label="Permalink to &quot;Roles&quot;">​</a></h2><h3 id="project-owner" tabindex="-1">Project Owner <a class="header-anchor" href="#project-owner" aria-label="Permalink to &quot;Project Owner&quot;">​</a></h3><ul><li>Sets product priorities and scope.</li><li>Approves phase plans and major RFCs.</li><li>Accepts security, privacy, maintenance, and business tradeoffs.</li><li>Decides when evidence is sufficient.</li></ul><h3 id="researcher" tabindex="-1">Researcher <a class="header-anchor" href="#researcher" aria-label="Permalink to &quot;Researcher&quot;">​</a></h3><ul><li>States the question and evaluation criteria before investigating.</li><li>Distinguishes evidence from inference.</li><li>Records sources, environment, limitations, and unanswered questions.</li><li>Does not present a recommendation as an accepted decision.</li></ul><h3 id="architect" tabindex="-1">Architect <a class="header-anchor" href="#architect" aria-label="Permalink to &quot;Architect&quot;">​</a></h3><ul><li>Converts needs and evidence into proposals.</li><li>Defines boundaries, alternatives, tradeoffs, security, and migration effects.</li><li>Keeps proposals consistent with the concept and active phase.</li></ul><h3 id="implementer" tabindex="-1">Implementer <a class="header-anchor" href="#implementer" aria-label="Permalink to &quot;Implementer&quot;">​</a></h3><ul><li>Works from an approved proposal or sufficiently bounded task.</li><li>Records assumptions rather than silently changing scope.</li><li>Adds tests, error handling, and documentation with behavior.</li></ul><h3 id="reviewer" tabindex="-1">Reviewer <a class="header-anchor" href="#reviewer" aria-label="Permalink to &quot;Reviewer&quot;">​</a></h3><ul><li>Checks correctness, scope, architecture, security, privacy, operability, and maintainability.</li><li>Verifies claims against code and tests rather than trusting generated summaries.</li></ul><h3 id="tester" tabindex="-1">Tester <a class="header-anchor" href="#tester" aria-label="Permalink to &quot;Tester&quot;">​</a></h3><ul><li>Verifies success, failure, recovery, resource, and real-hardware behavior.</li><li>Records commands, environment, results, and unresolved defects.</li></ul><p>One person or agent may perform several roles, but architect/implementer output should receive an independent review pass.</p><h2 id="choosing-the-right-document" tabindex="-1">Choosing the Right Document <a class="header-anchor" href="#choosing-the-right-document" aria-label="Permalink to &quot;Choosing the Right Document&quot;">​</a></h2><ul><li><strong>Research note:</strong> What is true or feasible?</li><li><strong>Experiment:</strong> Does a measurable hypothesis hold in a specified environment?</li><li><strong>RFC:</strong> What should the project build or standardize?</li><li><strong>ADR:</strong> What important choice was accepted, and why?</li><li><strong>Design brief:</strong> What user experience should be produced?</li><li><strong>Implementation plan:</strong> How will an accepted, bounded change be delivered?</li></ul><h2 id="work-item-readiness" tabindex="-1">Work Item Readiness <a class="header-anchor" href="#work-item-readiness" aria-label="Permalink to &quot;Work Item Readiness&quot;">​</a></h2><p>Implementation may begin when:</p><ul><li>the problem and user outcome are clear;</li><li>scope and non-scope are explicit;</li><li>acceptance criteria are testable;</li><li>dependencies and affected boundaries are known;</li><li>required decisions are accepted;</li><li>security and privacy implications are considered;</li><li>unresolved questions do not make the implementation direction ambiguous;</li><li>the work can be reviewed independently.</li></ul><h2 id="ai-agent-context" tabindex="-1">AI Agent Context <a class="header-anchor" href="#ai-agent-context" aria-label="Permalink to &quot;AI Agent Context&quot;">​</a></h2><p>Every implementation request should provide or link:</p><ul><li>the active phase plan;</li><li>relevant product use cases and terminology;</li><li>accepted RFCs and ADRs;</li><li>affected architecture documents;</li><li>security and data-handling constraints;</li><li>acceptance criteria and required verification;</li><li>files or components in scope;</li><li>explicit non-scope.</li></ul><p>Agents must label assumptions, preserve unrelated work, and avoid making hidden product or architecture decisions inside code.</p><h2 id="change-workflow" tabindex="-1">Change Workflow <a class="header-anchor" href="#change-workflow" aria-label="Permalink to &quot;Change Workflow&quot;">​</a></h2><ol><li>Define the problem and success criteria.</li><li>Decide whether research, an experiment, design work, or an RFC is needed.</li><li>Review and accept the necessary decision.</li><li>Write a bounded implementation plan.</li><li>Implement the smallest complete vertical slice.</li><li>Run proportionate automated and manual verification.</li><li>Review security, privacy, documentation, and operational effects.</li><li>Update current-state architecture and user/operations documentation.</li><li>Record remaining limitations and follow-up work.</li></ol><h2 id="definition-of-done" tabindex="-1">Definition of Done <a class="header-anchor" href="#definition-of-done" aria-label="Permalink to &quot;Definition of Done&quot;">​</a></h2><p>Applicable completion requirements must be selected before implementation. They may include:</p><ul><li>implementation and migrations;</li><li>unit, contract, integration, end-to-end, and hardware tests;</li><li>negative and failure-path tests;</li><li>documentation and examples;</li><li>security and privacy review;</li><li>configuration and deployment changes;</li><li>diagnostics and monitoring;</li><li>backup, restore, update, and removal behavior;</li><li>release notes and demonstration;</li><li>retrospective or recorded follow-up work.</li></ul><p>Code existing is not, by itself, completion.</p><h2 id="document-review-and-lifecycle" tabindex="-1">Document Review and Lifecycle <a class="header-anchor" href="#document-review-and-lifecycle" aria-label="Permalink to &quot;Document Review and Lifecycle&quot;">​</a></h2><ol><li>Author marks a document Draft.</li><li>Author resolves major unknowns and marks it Proposed.</li><li>Project owner accepts, rejects, or requests changes.</li><li>Accepted technical decisions may receive an ADR.</li><li>Implementation status is tracked separately from proposal acceptance.</li><li>Replacement documents link both directions and mark earlier work Superseded.</li><li>Historical reasoning is preserved rather than rewritten to make decisions appear inevitable.</li></ol>`,38)])])}const m=i(r,[["render",o]]);export{u as __pageData,m as default};
